Nuxt 3 Modules & Runtime Config:
// Custom Nuxt module
// modules/my-seo/index.ts
import { defineNuxtModule, addServerHandler, createResolver } from '@nuxt/kit';

export default defineNuxtModule({
  meta: {
    name: 'my-seo',
    configKey: 'seo',
  },
  defaults: {
    siteName: 'My Site',
    defaultDescription: 'Default description',
    twitterHandle: '@mysite',
  },
  setup(options, nuxt) {
    const resolver = createResolver(import.meta.url);

    // Add plugin for SEO head management
    addPlugin(resolver.resolve('./runtime/plugin'));

    // Add server route for sitemap
    addServerHandler({
      route: '/sitemap.xml',
      handler: resolver.resolve('./runtime/sitemap')
    });

    // Add composables
    addImports({
      name: 'useSeoMeta',
      from: resolver.resolve('./runtime/composables')
    });
  }
});

