Server Routes & API Layer:
// Nuxt 3 server routes
// server/api/products.get.ts
export default defineEventHandler(async (event) => {
  const query = getQuery(event);
  const { category, page = '1', limit = '20' } = query;

  const products = await Product.find({
    ...(category ? { category } : {}),
    status: 'published'
  })
    .skip((parseInt(page) - 1) * parseInt(limit))
    .limit(parseInt(limit))
    .sort({ createdAt: -1 });

  const total = await Product.countDocuments({
    ...(category ? { category } : {}),
    status: 'published'
  });

  return {
    products,
    pagination: {
      page: parseInt(page),
      limit: parseInt(limit),
      total,
      pages: Math.ceil(total / parseInt(limit))
    }
  };
});

// server/api/orders.post.ts
export default defineEventHandler(async (event) => {
  const body = await readBody(event);

  // Server-side validation
  const result = await orderSchema.safeParseAsync(body);
  if (!result.success) {
    throw createError({
      statusCode: 400,
      statusMessage: 'Validation failed',
      data: result.error.flatten()
    });
  }

  const order = await Order.create(result.data);
  await sendOrderConfirmation(order);

  return { id: order.id, status: 'created' };
});

// WebSocket handler
// server/websocket/chat.ts
export default defineWebSocketHandler({
  async open(peer) {
    await db.sessions.create({ peerId: peer.id });
  },
  async message(peer, message) {
    const { room, text } = JSON.parse(message.text());
    peer.send(JSON.stringify({ type: 'echo', text }));
  },
  async close(peer) {
    await db.sessions.deleteOne({ peerId: peer.id });
  }
});

